import {evaluate} from './engine.js';
import {money,date} from '../ui/format.js';
/** Guided, deterministic questions. No arbitrary SQL, no LLM claims. */
export function answer(question,d,result){
 const q=String(question).trim();const low=q.toLowerCase();
 if(q.length>500)return {title:'Question too long',text:'Please keep your question under 500 characters.',ids:[]};
 if(/\b(next|last|this) (week|month|year)|\btomorrow\b|\byesterday\b/.test(low))return {title:'Choose an explicit scenario',text:`This workspace uses a fixed ${d.snapshot} snapshot. Use the scenario controls for dates and delays, or ask about the current orders. Relative-date questions are not supported.`,ids:[]};
 const ids=[...new Set(q.toUpperCase().match(/ORD-\d{4}/g)||[])];
 if(ids.length>1)return {title:'Trace one order at a time',text:'Enter a single order ID to inspect its full allocation and evidence trail.',ids:[]};
 if(ids.length){const o=result.rows.find(o=>o.id===ids[0]);if(!o)return {title:'Order not found',text:`${ids[0]} is not in this dataset. Search the order workbench to find a valid order.`,ids:[]};return {title:`Order trace · ${o.id}`,text:`${o.customer} needs ${o.quantity} ${o.partName.toLowerCase()} units by ${date(o.requiredBy)}. ${o.atRisk?`${o.shortfall} units miss that requirement, exposing ${money(o.orderValuePaise)} in full order value.`:'Supply covers the requirement on time.'} Expected completion: ${date(o.expectedDate)}. ${o.unallocated?`${o.unallocated} units remain without supply.`:'Regular inbound supply is reserved for any backlog.'}`,ids:o.evidence,orderId:o.id};}
 if(/^(compare recovery( options)?|what (are|is) (the )?recovery( options)?|can (we|i) recover( these orders)?|recovery)$/i.test(q.replace(/[?.!]$/,''))){
 const before=evaluate(d,{...result.scenario,recovery:false});const after=evaluate(d,{...result.scenario,recovery:true});const rescued=before.rows.filter(o=>o.atRisk&&!after.rows.find(a=>a.id===o.id).atRisk);
 return {title:'Recovery comparison',text:`Using the compatible alternative changes at-risk orders from ${before.metrics.atRisk} to ${after.metrics.atRisk}. Exposure changes from ${money(before.metrics.exposurePaise)} to ${money(after.metrics.exposurePaise)}. It allocates ${after.metrics.recoveryUnits} premium units for ${money(after.metrics.recoveryCostPaise)} extra. ${rescued.length?`Orders recovered: ${rescued.map(o=>o.id).join(', ')}.`:'No additional orders meet their date.'} This comparison does not place a purchase order.`,ids:['ALT-01','DOC-01',...rescued.map(o=>o.id)]};
 }
 if(/^(what (inventory|stock)( is available)?|available inventory|inventory|stock)$/i.test(q.replace(/[?.!]$/,'')))return {title:'Snapshot inventory',text:d.parts.map(p=>`${p.name}: ${d.inventory.filter(i=>i.partId===p.id).reduce((n,i)=>n+i.quantity,0)} units`).join('. ')+'. Scenario allocation includes inbound supply separately.',ids:d.inventory.map(i=>i.id)};
 if(/^(why (are (these |the )?orders (delayed|at risk)|are they delayed)|explain (the )?(risk|delay)|show (the )?evidence)$/i.test(q.replace(/[?.!]$/,''))){const risky=result.rows.filter(o=>o.atRisk);return {title:risky.length?'Why orders are at risk':'All orders meet the modelled requirement',text:risky.length?`${risky.length} orders cannot obtain all components by their required-by date. The scenario uses a ${result.scenario.bufferDays}-day assembly buffer and reserves regular supply in due-date order. Open an order below to inspect exact dates and allocations. Supplier notes describe the source snapshot; slider values are planning assumptions.`:'No component shortages remain before required-by dates under the current assumptions.',ids:[...new Set(risky.flatMap(o=>o.evidence))]};}
 const supplier=d.suppliers.find(s=>low.includes(s.name.toLowerCase())||low.includes(s.name.split(' ')[0].toLowerCase()));
 const riskMatch=q.replace(/[?.!]$/,'').match(/^(?:which orders are at risk|orders at risk|show at.risk orders|list at.risk orders|how many orders are at risk|order exposure|exposure)(?: (?:for|from) (.+))?$/i);
 if(riskMatch?.[1]&&!supplier)return {title:'Supplier not found',text:'Name Aruna Components, Kaveri Electronics or Deccan Precision, or ask about all orders.',ids:[]};
 const riskIntent=!!riskMatch;
 if(riskIntent){const scoped=result.rows.filter(o=>!supplier||o.supplierIds.includes(supplier.id));const risky=scoped.filter(o=>o.atRisk);return {title:supplier?`Risk · ${supplier.name}`:'Current order exposure',text:`${risky.length} of ${scoped.length} orders are at risk, with ${money(risky.reduce((n,o)=>n+o.exposurePaise,0))} in full order value exposed and ${risky.reduce((n,o)=>n+o.shortfall,0)} units short by the required date. Exposure is not a revenue-loss forecast.`,ids:[...new Set(risky.flatMap(o=>o.evidence))]};}
 return {title:'Outside the guided question set',text:'Try “Which orders are at risk?”, “Why are these orders delayed?”, “Compare recovery options”, “What inventory is available?” or an order ID. Open-ended AI and multi-turn interpretation require the planned Snowflake integration.',ids:[]};
}
